"""matplotlib._docstring — docstring interpolation."""

class Substitution:
    def __init__(self, *args, **kwargs):
        if args and hasattr(args[0], 'items'):
            self.params = args[0]
        else:
            self.params = kwargs
    def __call__(self, func):
        return func
    def update(self, *args, **kwargs):
        self.params.update(*args, **kwargs)

def copy(source):
    def decorator(func):
        return func
    return decorator

def dedent_interpd(func):
    return func

def interpd(func):
    return func


# ─── Added: missing public helper from upstream _docstring.py ──────


def kwarg_doc(*args, **kwargs):
    """Decorator that inserts keyword-argument documentation into a
    function's docstring. The shim doesn't process docstrings, so we
    return the function unchanged."""
    if args and callable(args[0]):
        return args[0]
    return lambda fn: fn
